#!/usr/bin/env node
/**
 * ci:hooks-installed — the git hooks must actually be reachable from HERE.
 *
 * `core.hooksPath` is the RELATIVE path `.husky/_`, so git resolves it against
 * whichever working tree you are in. `.husky/_` is generated by husky at
 * install time and is gitignored, so it exists in the main checkout and does
 * NOT exist in a fresh `git worktree add`. The failure is silent: git finds no
 * pre-push hook, runs nothing, and the push succeeds having skipped the entire
 * gate chain and the production build.
 *
 * That happened on 2026-08-26 — a push from a fresh worktree landed on main
 * with no gates and no build, and looked identical to a verified one. Agents
 * work in worktrees constantly, so this is a hole every session can fall
 * through.
 *
 * Wired into the gate chain, which `push-with-gates.sh` runs before it pushes:
 * a hookless worktree now fails loudly on the sanctioned path instead of
 * shipping quietly.
 *
 * Fix when it fires:  sh scripts/worktree-setup.sh
 */
import { execFileSync } from 'node:child_process'
import fs from 'node:fs'
import path from 'node:path'

// CI runners check out fresh and never install husky; hooks are irrelevant there.
if (process.env.CI === 'true' || process.env.GITHUB_ACTIONS === 'true') {
  console.log('ci:hooks-installed — skipped (CI runner, hooks not used)')
  process.exit(0)
}

function git(...args) {
  try {
    return execFileSync('git', args, { encoding: 'utf8' }).trim()
  } catch {
    return ''
  }
}

const top = git('rev-parse', '--show-toplevel')
if (!top) {
  console.log('ci:hooks-installed — skipped (not a git working tree)')
  process.exit(0)
}

const configured = git('config', '--get', 'core.hooksPath')
// No hooksPath configured means git uses <git-dir>/hooks, which is per-worktree
// and shared from the common dir — the failure mode this gate exists for does
// not apply.
if (!configured) {
  console.log('ci:hooks-installed — skipped (no core.hooksPath configured)')
  process.exit(0)
}

const hooksDir = path.isAbsolute(configured) ? configured : path.join(top, configured)
const prePush = path.join(hooksDir, 'pre-push')
const preCommit = path.join(hooksDir, 'pre-commit')

const missing = [prePush, preCommit].filter((p) => !fs.existsSync(p))

if (missing.length === 0) {
  console.log(`ci:hooks-installed — OK (${configured} resolves to ${hooksDir})`)
  process.exit(0)
}

console.error('ci:hooks-installed FAILED')
console.error('')
console.error(`  core.hooksPath = ${configured}`)
console.error(`  resolves to    = ${hooksDir}`)
for (const m of missing) console.error(`  MISSING        = ${m}`)
console.error('')
console.error('  This working tree has NO git hooks. A push from here runs no gates and no')
console.error('  build, and succeeds looking exactly like a verified one.')
console.error('')
console.error('  Fix:  sh scripts/worktree-setup.sh')
process.exit(1)
